/** WKS-MOV-DATOS (WITH LOWER-BOUNDS): parámetro único que comparten todos los llamadores. */
public record MovimientoDatos(
        int funcion,                  // 9(02) COMP: 0 inicio, 1 alta, 2 baja, otro = grabar niveles
        int sistema,                  // 500, 555, 84, 87, 264, ...
        int producto,                 // REDEFINES TIPOCREDITO
        int instrumento,              // REDEFINES FONDO
        int sucProm,
        String contrato,              // 9(16) COMP: String para conservar ceros
        List<ClaveImporte> claves,    // WKS-TAB-CVEIMP OCCURS 5
        LocalDate fecMov, LocalTime horMov,
        LocalDate fecCont,            // 9(08) AAAAMMDD; REDEFINES AAMM(6) + DD(2) para la llave mensual
        LocalDate fecVal,
        long autoriza, long aut3er,
        Referencia refnum,            // 9(20) con tres vistas por sistema origen
        int cveMda, String numMda,    // NUMMDA-R: sucursal 9(04) + cuenta 9(16)
        int cveMde) {

    public record ClaveImporte(int cveTran, int indLey, int esqCon /* = TM */,
                               BigDecimal importe /* 9(14)V99 COMP, escala 2 */) {}

    /** WKS-MOV-REFNUM y sus REDEFINES S500, S087 y S404. */
    public sealed interface Referencia {
        record S500(int efec, int chvv, long referencia) implements Referencia {}
        record S087(int pm, long ref) implements Referencia {}
        record S404(int indEfectivo, BigDecimal porcentajeDescuento /* 99V99 */,
                    long zeros, int refS404) implements Referencia {}
        record Numerica(BigInteger valor) implements Referencia {}
    }

    /** WKS-MOV-FECCONT-AAMM: llave de B20SXSDOMENCON. */
    public YearMonth fecContAamm() { return YearMonth.from(fecCont); }
}

/**
 * S151LIB020. $SHARING = SHAREDBYRUNUNIT TEMPORARY: una instancia por unidad de ejecución.
 * En Spring el equivalente más cercano es un bean con alcance de job o de request,
 * con su propio estado de niveles (W77-NIV-*, W77-ULT-LEC).
 */
@Service
@Scope(value = "job", proxyMode = ScopedProxyMode.TARGET_CLASS)
@RequiredArgsConstructor
public class Lib020Service {

    public static final int RES_SOLO_NIVELES = 98;

    private final InicioLib020 inicio;          // 200000-INICIO
    private final ProcesoSdoMov proceso;        // 300000-PROCESO-SDOMOV
    private final NivelesLib020 niveles;        // 100100-GRABA-NIVEL-SDOMOV

    /** PROCEDURE DIVISION USING WKS-MOV-DATOS, W77-RES-FIL, W77-RES-LIB. */
    public Resultado ejecuta(MovimientoDatos mov) {
        return switch (mov.funcion()) {
            case 0    -> inicio.inicia(mov);
            case 1, 2 -> proceso.procesa(mov);
            default   -> {
                niveles.grabaNiveles();
                yield Resultado.mov(RES_SOLO_NIVELES);   // MOVE 98 TO W77-RES-MOV
            }
        };
    }

    public record Resultado(int resMov, int resLib) {
        static Resultado mov(int r) { return new Resultado(r, 0); }
    }
}

@Service
@RequiredArgsConstructor
class ProcesoSdoMov {

    private final ControlNivelRepository nivelSdo;    // B00 en SDODB
    private final ControlNivelRepository nivelMov;    // B00 en MOVDB
    private final MovimientosService movimientos;     // 310000-PROCESA-MOVTOS
    private final SaldosService saldos;               // 510000-PROCESA-SDOS
    private final NivelesLib020 niveles;

    @Transactional   // LOCK SDODB + LOCK MOVDB: una sola transacción para ambas bases
    Lib020Service.Resultado procesa(MovimientoDatos mov) {
        long lecSdo = nivelSdo.lecArcDia(), lecMov = nivelMov.lecArcDia();
        boolean actMov, actSdo;
        if (mov.sistema() == 500 || mov.sistema() == 555) {
            actSdo = lecSdo <= lecMov;    // = actualiza ambas; < solo saldos
            actMov = lecSdo >= lecMov;    // > solo movimientos (la base atrasada se pone al corriente)
        } else {
            actSdo = true;
            actMov = false;
        }
        if (actMov) {
            boolean detalla = !(mov.sistema() == 84 && mov.instrumento() != 15 && mov.instrumento() != 17);
            if (detalla) movimientos.procesa(mov);
            niveles.grabaNivMovs(mov);
        }
        if (actSdo) {
            saldos.procesa(mov);
            niveles.grabaNivSdos(mov);
        }
        // W77-ACT-SDO = 2 (solo grabar nivel de saldos) nunca se asigna en el fuente: rama omitida.
        return niveles.ultimaLecturaResultado(mov, actMov, actSdo);   // W77-ULT-LEC
    }
}

@Component
@RequiredArgsConstructor
class NivelesLib020 {

    private final ControlNivelRepository nivelMov;
    private final ControlNivelRepository nivelSdo;
    private long nivMovOk, nivMovInf, nivMovErr;       // W77-NIV-MOVOK / MOVIN / MOVER

    /** 300100-GRABA-NIVMOVS: los tres niveles del día suben juntos a la autorización del movimiento. */
    void grabaNivMovs(MovimientoDatos mov) {
        ControlNivel b00 = nivelMov.delDia();
        b00.setSecuencias(nivMovOk, nivMovInf, nivMovErr);
        if (mov.autS151() > b00.getLecArcDia() || mov.autS151() > b00.getMovCicDia()
                || mov.autS151() > b00.getSdoCicDia()) {
            b00.setNiveles(mov.autS151());             // LECARCDIA = MOVCICDIA = SDOCICDIA
        }
        nivelMov.save(b00);                            // STORE MOVDB (siempre)
    }

    /** 300200-GRABA-NIVSDOS: a diferencia de MOVDB, solo hace STORE si el nivel cambió. */
    void grabaNivSdos(MovimientoDatos mov) {
        ControlNivel b00 = nivelSdo.delDia();
        if (mov.autS151() > b00.getLecArcDia() || mov.autS151() > b00.getMovCicDia()
                || mov.autS151() > b00.getSdoCicDia()) {
            b00.setNiveles(mov.autS151());
            nivelSdo.save(b00);
        }
    }
}

@Component
@RequiredArgsConstructor
class DmsErrorHandler {

    private final AlertaOperacion alertas;

    /**
     * 900000-CHECA-STATUS. El fuente registra categoría, tipo y estructura del error,
     * los niveles de lectura y ejecuta STOP "DAR OK PARA CONT": la tarea queda detenida
     * hasta que un operador responde OK, y luego CONTINÚA con la siguiente instrucción.
     */
    void checa(DataAccessException e, String base, Niveles niv) {
        log.error("BASE DATOS {} ERROR EN BD {} lecSdo={} lecMov={} ultLec={}",
                  base, e.getMostSpecificCause().getMessage(),
                  niv.lecSdo(), niv.lecMov(), niv.ultLec());
        alertas.publica("S151LIB020 error de base de datos en " + base);
        // En lugar de esperar al operador y continuar, se revierte la transacción:
        throw new Lib020DatosException(base, e);       // W77-RES-MOV = categoría DMSII
    }
}

/** WKS-TAB-APUNCVES (OCCURS 9999) + WKS-TAB-AFECSDOS (OCCURS 5000 x 6). */
@Component
@RequiredArgsConstructor
public class AfectacionCatalogo {

    public enum Afectacion { CARGO, ABONO }        // WKS-TIP-AFEC 1 / 2
    public record Afecta(int tipoSaldo, Afectacion afectacion) {}   // WKS-TIP-CVE 9(03)

    private final CatalogoS080Client s080;          // L710_CONSUL_DETALLE IN ESTRUCTURA
    private Map<Integer, List<Afecta>> porClave = Map.of();

    void carga(int sistema) {
        Map<Integer, List<Afecta>> m = new HashMap<>();
        for (var r : s080.detalle(/* catálogo del sistema */)) {   // RESULT 1 = hay más páginas, 0 = última, 20 = sin datos
            if (r.dato(1) != sistema) continue;
            var lista = m.computeIfAbsent((int) r.dato(2), k -> new ArrayList<>());
            if (lista.size() < 6) {                // 230110-BUSCA-SPC: primer hueco libre de 6
                lista.add(new Afecta((int) r.dato(3),
                        r.dato(4) == 1 ? Afectacion.CARGO : Afectacion.ABONO));
            }
        }
        if (m.isEmpty()) {
            throw new IllegalStateException("Sin claves de afectación para " + sistema);  // W77-RES-MOV 999
        }
        porClave = Map.copyOf(m);
    }

    public List<Afecta> de(int cveTran) { return porClave.getOrDefault(cveTran, List.of()); }
}

/**
 * 510000-PROCESA-SDOS, primer bloque. Para S087 el "producto" es un plazo y se agrupa
 * en el límite inferior del tramo. Los límites se trasladan a application.yml tal como están.
 */
static int tramoS087(int instrumento, int producto) {
    return switch (instrumento) {
        case 4, 7 -> tramo(producto, new int[][]{
                {1, 6, 1}, {7, 13, 7}, {14, 20, 14}, {21, 27, 21}, {28, 41, 28}, {42, 62, 42},
                {63, 90, 63}, {91, 181, 91}, {182, 272, 182}, {273, 377, 273}}, 378);
        case 3, 5 -> tramo(producto, new int[][]{
                {90, 119, 90}, {120, 149, 120}, {150, 179, 150}, {180, 367, 180},
                {370, 719, 370}}, 720);      // 368 y 369 no caen en ningún tramo: van a 720
        case 1    -> tramo(producto, new int[][]{
                {1, 6, 1}, {7, 13, 7}, {14, 29, 14}, {30, 59, 30}, {60, 90, 60},
                {91, 119, 91}, {120, 179, 120}}, 180);
        default   -> producto;
    };
}

/** El ELSE final del IF anidado captura todo lo que no cae en un tramo, incluidos valores bajos. */
private static int tramo(int p, int[][] tramos, int resto) {
    for (int[] t : tramos) {
        if (p >= t[0] && p <= t[1]) return t[2];
    }
    return resto;
}

@Service
@RequiredArgsConstructor
class SaldosService {

    private final AfectacionCatalogo catalogo;
    private final SaldoMensualRepository b20;      // S151B20SDOMENCON
    private final PosicionDiariaRepository b70;    // S151B70POSICION

    /** 520000-ACTUALIZA-SDOS VARYING W77-I FROM 1 BY 1 UNTIL W77-I > 5. */
    void actualiza(MovimientoDatos mov, SaldoMensual mensual, PosicionDiaria posicion) {
        if (mov.origen() != 1 && mov.origen() != 3) return;
        boolean contratoMensual = (mov.sistema() == 500 || mov.sistema() == 555)
                && mov.producto() == 1 && mov.instrumento() == 3;

        for (var clave : mov.claves()) {
            if (clave.cveTran() == 0) continue;            // no corta: revisa las cinco posiciones
            List<AfectacionCatalogo.Afecta> afecta = catalogo.de(clave.cveTran());
            if (afecta.isEmpty()) continue;                // W77-J = 0: la clave no afecta saldos
            if (contratoMensual) {
                afecta.forEach(a -> mensual.aplica(a, mov.funcion(), clave.importe()));   // 522000
                mensual.setStaMov(1);
                b20.save(mensual);
            }
            afecta.forEach(a -> posicion.aplica(a, mov.funcion(), clave.importe()));      // 530000
            b70.save(posicion);
        }
    }
}

@Entity
@Table(name = "s151_b20_sdomencon")
class SaldoMensual {

    @EmbeddedId private SaldoMensualId id;   // AAMM, contrato, moneda, producto, instrumento
    @ElementCollection private List<BigDecimal> sd;      // B20-SDO-SD(1..10)
    @ElementCollection private List<Integer> cntMov;     // B20-SDO-CNTMOV(1..10)

    /** 522000-ACT-SDOSXCONT-MES. Función 1 aplica; función 2 revierte. */
    void aplica(AfectacionCatalogo.Afecta a, int funcion, BigDecimal importe) {
        int t = a.tipoSaldo();
        if (t >= 11) {
            int indice = ((t + 1) % 12) + 1;            // DIVIDE (T + 1) BY 12 REMAINDER, ADD 1 (W77-REMANENTE)
            saldoB21.aplica(this, indice, a, funcion, importe);   // 522100 (B21SXSDMENCON1)
            // y si CVETRAN = 18, producto 84, instrumento 15: 522200-ACT-SDOSXCONT-MES084
            return;
        }
        int signo = switch (funcion) {
            case 1 -> a.afectacion() == Afectacion.CARGO ? -1 : 1;   // cargo resta, abono suma
            case 2 -> a.afectacion() == Afectacion.CARGO ? 1 : -1;   // la baja invierte el signo
            default -> 0;
        };
        if (signo == 0) return;
        int idx = t - 1;
        // Suma exacta entre importes con escala 2: no hay redondeo que replicar.
        sd.set(idx, sd.get(idx).add(importe.multiply(BigDecimal.valueOf(signo))));
        cntMov.set(idx, cntMov.get(idx) + (funcion == 1 ? 1 : -1));
    }
}
